package com.meridian.keystone; import com.meridian.keystone.model.*; import com.meridian.keystone.repo.UserRepo; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; @SpringBootApplication public class KeystoneApplication { public static void main(String[] args){ SpringApplication.run(KeystoneApplication.class,args);} @Bean PasswordEncoder enc(){return new BCryptPasswordEncoder();} @Bean CommandLineRunner seed(UserRepo repo, PasswordEncoder enc){return a->{if(repo.count()==0){repo.save(new User("manager@meridian.com",enc.encode("Manager@123"),Role.MANAGER));repo.save(new User("tech1@meridian.com",enc.encode("Tech@123"),Role.TECHNICIAN));repo.save(new User("customer@meridian.com",enc.encode("Cust@123"),Role.CUSTOMER));System.out.println("Seeded 3 users");}};}}
